import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { StudyList } from './components/StudyList';
import { RisWorklist } from './components/RisWorklist';
import { StudyDetails } from './components/StudyDetails';
import { LinkConfirmationModal } from './components/LinkConfirmationModal';
import { SettingsModal } from './components/SettingsModal';
import { ConnectionStatus, DicomStudy, WorklistItem, AppSettings } from './types';
import { MOCK_RECEIVED, MOCK_WORKLIST } from './constants';
import { Activity, Link2, AlertTriangle, ArrowRight } from 'lucide-react';

// Utility for safe ID generation (fallback for environments without secure crypto)
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) {
      // Fallback if crypto.randomUUID fails
    }
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

const App: React.FC = () => {
  // Config State
  const [appSettings, setAppSettings] = useState<AppSettings>({
    pacs: {
      aeTitle: 'PRESERVER_SCP',
      port: 104,
      wsUrl: 'ws://localhost:8080/dicom-receiver'
    },
    ris: {
      enabled: true,
      aeTitle: 'RIS_SERVER',
      host: '192.168.1.10',
      port: 104,
      pollingInterval: 30
    }
  });

  // State
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [studies, setStudies] = useState<DicomStudy[]>(MOCK_RECEIVED);
  const [worklist, setWorklist] = useState<WorklistItem[]>(MOCK_WORKLIST);

  // Selection Logic
  const [selectedStudy, setSelectedStudy] = useState<DicomStudy | null>(null); // For linking
  const [selectedWorklist, setSelectedWorklist] = useState<WorklistItem | null>(null); // For linking

  // Modal State
  const [previewStudy, setPreviewStudy] = useState<DicomStudy | null>(null); // For viewing details
  const [showLinkConfirmation, setShowLinkConfirmation] = useState(false); // For confirming link
  const [showSettings, setShowSettings] = useState(false); // For settings

  // WebSocket References
  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<number | null>(null);

  // WebSocket Connection Logic
  useEffect(() => {
    const connect = () => {
      // Prevent multiple connections
      if (socketRef.current?.readyState === WebSocket.OPEN || socketRef.current?.readyState === WebSocket.CONNECTING) {
        return;
      }

      setConnectionStatus(ConnectionStatus.CONNECTING);

      try {
        const ws = new WebSocket(appSettings.pacs.wsUrl);
        socketRef.current = ws;

        ws.onopen = () => {
          setConnectionStatus(ConnectionStatus.CONNECTED);
          console.log('Connected to PACS Receiver');
          // Clear any pending reconnects if successful
          if (reconnectTimeoutRef.current) {
            window.clearTimeout(reconnectTimeoutRef.current);
            reconnectTimeoutRef.current = null;
          }
        };

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            // Transform incoming data to internal model
            const newStudy: DicomStudy = {
              id: generateId(),
              patientName: data.patientName || data.PatientName || 'Unknown',
              patientId: data.patientId || data.PatientID || 'N/A',
              birthDate: data.birthDate || data.PatientBirthDate || 'N/A',
              modality: data.modality || data.Modality || 'OT',
              studyDate: data.studyDate || new Date().toISOString().split('T')[0],
              accessionNumber: data.accessionNumber || data.AccessionNumber || 'N/A',
              description: data.description || data.StudyDescription || '',
              studyInstanceUID: data.studyInstanceUID || data.StudyInstanceUID || '',
              receivedAt: new Date().toLocaleTimeString(),
              status: 'received'
            };

            setStudies(prev => [newStudy, ...prev]);
          } catch (e) {
            console.error('Failed to parse DICOM event', e);
          }
        };

        ws.onerror = (e) => {
          console.warn(`WebSocket connection error to ${appSettings.pacs.wsUrl}. Backend might be offline.`);
          setConnectionStatus(ConnectionStatus.ERROR);
        };

        ws.onclose = () => {
          setConnectionStatus(ConnectionStatus.DISCONNECTED);
          socketRef.current = null;

          // Auto-reconnect after 3 seconds if not intentionally closed (cleanup handles intentional close)
          reconnectTimeoutRef.current = window.setTimeout(() => {
             connect();
          }, 3000);
        };

      } catch (e) {
        console.error("WebSocket creation failed", e);
        setConnectionStatus(ConnectionStatus.ERROR);
        // Retry even if creation fails (e.g. invalid URL might be fixed by user later, but here we retry logic)
        reconnectTimeoutRef.current = window.setTimeout(() => {
          connect();
       }, 5000);
      }
    };

    connect();

    return () => {
      if (socketRef.current) {
        socketRef.current.onclose = null; // Prevent onclose from triggering reconnect during cleanup
        socketRef.current.close();
        socketRef.current = null;
      }
      if (reconnectTimeoutRef.current) {
        window.clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [appSettings.pacs.wsUrl]);

  const handleLinkClick = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;
    setShowLinkConfirmation(true);
  }, [selectedStudy, selectedWorklist]);

  const handleConfirmLink = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;

    // Simulate linking logic (API call would go here)
    // Update Worklist status locally to simulate completion
    setWorklist(prev => prev.map(item => 
      item.id === selectedWorklist.id 
        ? { ...item, status: 'completed' } 
        : item
    ));

    // Reset selection and close modal
    setShowLinkConfirmation(false);
    setSelectedStudy(null);
    setSelectedWorklist(null);
  }, [selectedStudy, selectedWorklist]);

  const handleSaveSettings = (newSettings: AppSettings) => {
    setAppSettings(newSettings);
  };

  // Demo: Simulate receiving a study if connected (Mock Data Injection)
  useEffect(() => {
    let interval: number;
    if (connectionStatus === ConnectionStatus.CONNECTED) {
       interval = window.setInterval(() => {
         // Only mock if we are "connected" (in this demo app, we fake connection usually, 
         // but if WS is real, we might want to disable this or keep it for demo purposes)
         // Reducing frequency for less noise
         if (Math.random() > 0.95) {
           const modalities = ['CT', 'MR', 'DX', 'US'];
           const names = ['Souza, Joao', 'Lima, Pedro', 'Gomes, Ana', 'Ferreira, Clara'];
           const birthYears = [1960, 1975, 1988, 1995, 2001];

           const randMod = modalities[Math.floor(Math.random() * modalities.length)];
           const randName = names[Math.floor(Math.random() * names.length)];
           const randYear = birthYears[Math.floor(Math.random() * birthYears.length)];
           const randMonth = Math.floor(Math.random() * 12) + 1;
           const randDay = Math.floor(Math.random() * 28) + 1;
           const birthDate = `${randDay.toString().padStart(2,'0')}/${randMonth.toString().padStart(2,'0')}/${randYear}`;

           const simulatedStudy: DicomStudy = {
             id: generateId(),
             patientName: randName,
             patientId: `P-${Math.floor(Math.random()*10000)}`,
             birthDate: birthDate,
             modality: randMod,
             studyDate: new Date().toISOString().split('T')[0],
             accessionNumber: `ACC-2024-${Math.floor(Math.random()*999)}`,
             description: `${randMod} Exam Routine`,
             studyInstanceUID: `1.2.3.4.5.${Date.now()}`,
             receivedAt: new Date().toLocaleTimeString(),
             status: 'received'
           };
           setStudies(prev => [simulatedStudy, ...prev]);
         }
       }, 3000);
    }
    return () => clearInterval(interval);
  }, [connectionStatus]);

  // Check data consistency for Floating Bar display
  const namesMatch = selectedStudy && selectedWorklist 
    ? selectedStudy.patientName.toLowerCase().replace(/[^a-z0-9]/g, '') === selectedWorklist.patientName.toLowerCase().replace(/[^a-z0-9]/g, '')
    : false;

  const birthDatesMatch = selectedStudy && selectedWorklist
    ? selectedStudy.birthDate === selectedWorklist.birthDate
    : false;

  return (
    <div className="min-h-screen p-4 md:p-6 max-w-[1600px] mx-auto pb-24 flex flex-col relative">
      <Header 
        onOpenSettings={() => setShowSettings(true)}
      />

      {/* Main Content: Split Screen */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-[600px]">

        {/* Left Panel: PACS Received */}
        <div className="flex flex-col h-full shadow-2xl shadow-black/20">
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-lg font-bold text-slate-200 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-cyan-500"></span>
              PACS Received
            </h2>
            <div className="flex items-center gap-2">
               <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Origem</span>
               <span className="text-xs bg-slate-800 text-slate-400 px-2 py-1 rounded-full border border-slate-700">
                {studies.length}
              </span>
            </div>
          </div>
          <div className="flex-1 overflow-hidden relative ring-1 ring-slate-800 rounded-lg">
            <StudyList 
              studies={studies} 
              onSelect={setSelectedStudy} 
              onDetails={setPreviewStudy}
              selectedId={selectedStudy?.id}
            />
          </div>
        </div>

        {/* Right Panel: RIS Worklist */}
        <div className="flex flex-col h-full shadow-2xl shadow-black/20">
          <div className="mb-3 flex items-center justify-between">
             <h2 className="text-lg font-bold text-slate-200 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
              RIS Worklist
            </h2>
            <div className="flex items-center gap-2">
               <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Destino</span>
               <span className="text-xs bg-slate-800 text-slate-400 px-2 py-1 rounded-full border border-slate-700">
                {worklist.length}
              </span>
            </div>
          </div>
          <div className="flex-1 overflow-hidden relative ring-1 ring-slate-800 rounded-lg">
            <RisWorklist 
              worklist={worklist} 
              onSelect={setSelectedWorklist}
              selectedId={selectedWorklist?.id}
            />
          </div>
        </div>

      </div>

      {/* Floating Action Bar for Linking */}
      {selectedStudy && selectedWorklist && !showLinkConfirmation && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom-4 fade-in duration-300 w-[90%] max-w-3xl">
          <div className="bg-slate-900 border border-slate-700 p-4 rounded-xl shadow-2xl shadow-black flex flex-col md:flex-row items-center gap-4 justify-between relative overflow-hidden">
            {/* Background Gradient */}
            <div className="absolute inset-0 bg-gradient-to-r from-cyan-900/20 via-transparent to-indigo-900/20 pointer-events-none" />

            <div className="flex items-center gap-4 relative z-10 w-full md:w-auto flex-1">
              <div className="bg-slate-800 p-2.5 rounded-lg border border-slate-700 hidden md:block">
                 <Link2 size={24} className="text-white" />
              </div>

              <div className="flex-1 grid grid-cols-[1fr_auto_1fr] gap-4 items-center">
                {/* Source Info */}
                <div className="text-right">
                  <div className="text-xs font-bold text-cyan-500 uppercase tracking-wider mb-0.5">PACS (Origem)</div>
                  <div className="text-sm font-bold text-slate-200">{selectedStudy.patientName}</div>
                  <div className="text-xs text-slate-400 flex items-center justify-end gap-1">
                    {selectedStudy.birthDate} 
                    {!birthDatesMatch && <AlertTriangle size={10} className="text-red-500" />}
                  </div>
                </div>

                {/* Arrow */}
                <div className="flex flex-col items-center justify-center">
                   <ArrowRight size={20} className="text-slate-600" />
                </div>

                {/* Dest Info */}
                <div className="text-left">
                  <div className="text-xs font-bold text-indigo-500 uppercase tracking-wider mb-0.5">RIS (Destino)</div>
                  <div className="text-sm font-bold text-slate-200">{selectedWorklist.patientName}</div>
                  <div className="text-xs text-slate-400 flex items-center gap-1">
                    {!birthDatesMatch && <AlertTriangle size={10} className="text-red-500" />}
                    {selectedWorklist.birthDate}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-col items-end gap-2 w-full md:w-auto relative z-10">
              {(!namesMatch || !birthDatesMatch) && (
                <div className="text-[10px] text-red-400 font-bold bg-red-500/10 border border-red-500/20 px-2 py-1 rounded w-full text-center">
                   {!namesMatch && !birthDatesMatch ? 'NOMES E DATAS DIFERENTES' : !namesMatch ? 'NOMES DIFERENTES' : 'DATAS DE NASCIMENTO DIFERENTES'}
                </div>
              )}
              <button 
                onClick={handleLinkClick}
                className="w-full md:w-auto bg-gradient-to-r from-cyan-600 to-indigo-600 hover:from-cyan-500 hover:to-indigo-500 text-white shadow-lg shadow-cyan-900/20 px-6 py-3 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 whitespace-nowrap"
              >
                <Link2 size={16} />
                Confirmar Vínculo
              </button>
            </div>

          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      {showLinkConfirmation && selectedStudy && selectedWorklist && (
        <LinkConfirmationModal 
          study={selectedStudy}
          worklistItem={selectedWorklist}
          onConfirm={handleConfirmLink}
          onCancel={() => setShowLinkConfirmation(false)}
        />
      )}

      {/* Settings Modal */}
      <SettingsModal 
        isOpen={showSettings}
        onClose={() => setShowSettings(false)}
        settings={appSettings}
        onSave={handleSaveSettings}
      />

      {/* Details Modal */}
      {previewStudy && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/70 backdrop-blur-[2px] transition-opacity animate-in fade-in duration-200">
          <div className="w-full max-w-2xl h-[80vh] md:h-auto md:max-h-[85vh] animate-in zoom-in-95 duration-200">
             <StudyDetails 
               study={previewStudy} 
               onClose={() => setPreviewStudy(null)}
             />
          </div>
        </div>
      )}

      {/* Footer Status Indicator */}
      <div className="fixed bottom-4 right-4 z-40">
         <div className={`
           bg-slate-900/90 backdrop-blur border px-3 py-1.5 rounded-full shadow-xl text-[10px] flex items-center gap-2 transition-colors
           ${connectionStatus === ConnectionStatus.ERROR 
             ? 'border-red-500/50 text-red-400' 
             : 'border-slate-700 text-slate-500'}
         `}>
            <Activity size={10} className={connectionStatus === ConnectionStatus.CONNECTED ? "text-emerald-500 animate-pulse" : connectionStatus === ConnectionStatus.ERROR ? "text-red-500" : "text-slate-600"} />
            {connectionStatus === ConnectionStatus.CONNECTED ? `Connected to ${appSettings.pacs.aeTitle}` : connectionStatus === ConnectionStatus.ERROR ? "Connection Failed (Retrying...)" : "Disconnected"}
         </div>
      </div>

    </div>
  );
};

export default App;
